CREATE FUNCTION public.can_read_academic_content() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=auth.uid() AND u.email_confirmed_at IS NOT NULL) AND public.is_approved_member(auth.uid()) $$;
REVOKE ALL ON FUNCTION public.can_read_academic_content() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_read_academic_content() TO authenticated;
ALTER POLICY content_member_published ON public.content_items USING(published AND public.can_read_academic_content());
ALTER POLICY categories_member ON public.resource_categories USING(public.can_read_academic_content());
ALTER POLICY academic_files_read ON storage.objects USING(bucket_id='academic-resources' AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.content_items c WHERE c.file_path=name AND c.published AND public.can_read_academic_content())));
CREATE OR REPLACE FUNCTION public.approved_whatsapp_link() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_read_academic_content() THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN (SELECT whatsapp_link FROM public.membership_settings WHERE id AND show_whatsapp_to_members); END $$;
CREATE FUNCTION public.validate_academic_content() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE key text; link text; BEGIN IF length(NEW.description)>12000 OR jsonb_typeof(NEW.details)<>'object' THEN RAISE EXCEPTION 'Invalid content'; END IF; FOREACH key IN ARRAY ARRAY['external_url','meeting_url'] LOOP link:=coalesce(NEW.details->>key,''); IF link<>'' AND link !~ '^https://[A-Za-z0-9.-]+(:[0-9]+)?([/?#][^[:space:]]*)?$' THEN RAISE EXCEPTION 'HTTPS link required'; END IF; END LOOP; IF NEW.kind='resources' AND ((NEW.file_path IS NULL AND coalesce(NEW.details->>'external_url','')='') OR (NEW.file_path IS NOT NULL AND coalesce(NEW.details->>'external_url','')<>'')) THEN RAISE EXCEPTION 'Choose file or link'; END IF; IF NEW.kind<>'resources' AND NEW.file_path IS NOT NULL THEN RAISE EXCEPTION 'Files only belong to resources'; END IF; IF NEW.kind='events' THEN IF coalesce(NEW.details->>'starts_at','')='' THEN RAISE EXCEPTION 'Event date required'; END IF; PERFORM (NEW.details->>'starts_at')::timestamptz; END IF; IF NEW.kind='mentorship' AND coalesce(NEW.details->>'status','') NOT IN ('Open','Closed') THEN RAISE EXCEPTION 'Invalid mentorship status'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_academic_content BEFORE INSERT OR UPDATE ON public.content_items FOR EACH ROW EXECUTE FUNCTION public.validate_academic_content();